/// <summary>
/// Group of employment categories, used on the Group level of the indirect cost matrix.
/// Shared across legal entities, like <c>BenefitEmploymentCategory</c>.
/// </summary>
public class HOGpmaEmploymentCategoryGroup extends common
{
}

Method.Source:
/// <summary>
/// Finds an employment category group.
/// </summary>
/// <param name = "_groupId">The group ID.</param>
/// <param name = "_forUpdate">true to select the record for update.</param>
/// <returns>The group, or an empty buffer.</returns>
public static HOGpmaEmploymentCategoryGroup find(HOGpmaEmploymentCategoryGroupId _groupId, boolean _forUpdate = false)
{
    HOGpmaEmploymentCategoryGroup categoryGroup;

    if (_groupId)
    {
        categoryGroup.selectForUpdate(_forUpdate);

        select firstonly categoryGroup
            where categoryGroup.EmploymentCategoryGroupId == _groupId;
    }

    return categoryGroup;
}

/// <summary>
/// Checks whether an employment category group exists.
/// </summary>
/// <param name = "_groupId">The group ID.</param>
/// <returns>true if the group exists; otherwise, false.</returns>
public static boolean exist(HOGpmaEmploymentCategoryGroupId _groupId)
{
    return _groupId
        && (select firstonly RecId from HOGpmaEmploymentCategoryGroup
                where HOGpmaEmploymentCategoryGroup.EmploymentCategoryGroupId == _groupId).RecId != 0;
}

/// <summary>
/// Prevents deleting a group that an employment category or the indirect cost matrix
/// of any legal entity still uses.
/// </summary>
/// <returns>true if the group can be deleted; otherwise, false.</returns>
public boolean validateDelete()
{
    boolean ret = super();

    if (ret)
    {
        BenefitEmploymentCategory category;
        HOGpmaIndirectCostMatrix  matrix;

        select firstonly RecId from category
            where category.HOGpmaEmploymentCategoryGroupId == this.EmploymentCategoryGroupId;

        select firstonly crosscompany RecId from matrix
            where matrix.EmploymentCategoryCode     == TableGroupAll::GroupId
               && matrix.EmploymentCategoryRelation == this.EmploymentCategoryGroupId;

        if (category.RecId || matrix.RecId)
        {
            ret = checkFailed(strFmt("@HOGpma:ErrGroupInUse", this.EmploymentCategoryGroupId));
        }
    }

    return ret;
}
